g = {('A','B'): {'S','C'}, ('B','C'): {'S'}, ('B','A'): {'A'}, ('C','C'): {'B'}}
t = {'a': {'A','C'}, 'b': {'B'}}
w = input().strip()
n = len(w)
T = [[set() for _ in range(n)] for _ in range(n)]
for i, ch in enumerate(w):
    T[i][i] = set(t[ch])
for l in range(2, n + 1):
    for i in range(n - l + 1):
        j = i + l - 1
        for k in range(i, j):
            for X in T[i][k]:
                for Y in T[k + 1][j]:
                    T[i][j] |= g.get((X, Y), set())
print('YES' if 'S' in T[0][n - 1] else 'NO')

